  async function caseDetail(id,token){let c;try{c=await api('platform.caseDetail',{id});}catch(e){if(token===renderToken)$('#main').innerHTML=title('办件不可访问',e.message);return;}if(token!==renderToken)return;
    const user=state().D.user,manager=['平台管理员','流程管理员'].includes(user.role),handler=!!c.canHandle,active=['在办','已挂起'].includes(c.status);
    $('#main').innerHTML=`<div class="pc-detail-back"><a href="#/${state().mode}/workbench">← 返回业务工作台</a></div>${title(c.name,`${c.category} · ${c.region} · 流程版本 v${c.workflow.version}`,tag(c.status))}<div class="pc-case-flow">${c.workflow.nodes.map((n,i)=>`<div class="${i<c.nodeIndex||c.status==='已办结'?'done':i===c.nodeIndex?'current':''}"><span>${i<c.nodeIndex||c.status==='已办结'?icon('check'):i+1}</span><strong>${esc(n.name)}</strong><small>${esc(rows('users').find(u=>u.id===n.assigneeId)?.name||n.assigneeId)}</small></div>`).join('')}</div><div class="pc-two-column pc-case-columns"><section class="panel pc-padding"><div class="pc-panel-head"><h2>申请材料</h2><span>表单 v${c.form.version}</span></div><dl class="pc-definition">${c.form.fields.map(f=>`<dt>${esc(f.label)}</dt><dd>${esc(c.formData[f.key]??'—')}</dd>`).join('')}<dt>办理截止</dt><dd>${fmt(c.dueAt)}</dd><dt>合规状态</dt><dd>${esc(c.compliance)}</dd></dl>${c.ruleResults.length?`<h3>表单规则校验</h3>${c.ruleResults.map(r=>notice(r.name+'：'+(r.passed?'通过':'未通过'))).join('')}`:''}<h3>知识依据</h3>${c.workflow.knowledgeIds.map(id=>state().D.knowledge.find(k=>k.id===id)).filter(Boolean).map(k=>btn(esc(k.name),'portalKnowledge',k.id,'small','book')).join('')}<div class="pc-case-related">${btn('智能辅助','pc-case-ai',c.id,'','sparkles')}${btn('查看场景','pc-case-map',c.id,'','layers')}${btn('生成办理文书','pc-document',c.id,'','file')}${(manager||handler)?btn('合规核查','pc-compliance',c.id,'','shield'):''}${manager&&active?btn('发起督办','pc-supervise',c.id,'','bell'):''}</div></section><aside><section class="panel pc-padding"><h2>当前办理</h2><p>${esc(c.workflow.nodes[c.nodeIndex]?.name)} · ${esc(rows('users').find(u=>u.id===c.assigneeId)?.name||c.assigneeId)}</p>${active?`<form id="pc-case-action" data-id="${c.id}" data-rev="${c.rev}"><label class="pc-field"><span>办理意见</span><textarea name="note" required placeholder="填写办理依据与说明" rows="4"></textarea></label><div class="pc-phrases">${rows('businessAssets').filter(r=>r.kind==='常用语管理').map(r=>btn(esc(r.name),'pc-phrase',r.id,'text small')).join('')}</div><div class="pc-case-actions">${handler&&c.status==='在办'?'<button class="btn primary" name="command" value="complete">完成当前节点</button>':''}${handler&&c.nodeIndex>0&&c.status==='在办'?'<button class="btn" name="command" value="return">回退上一步</button>':''}${handler&&c.status==='在办'?btn('协办 / 委办','pc-transfer',c.id,''):''}${manager?`<button class="btn" name="command" value="${c.status==='在办'?'suspend':'resume'}">${c.status==='在办'?'挂起':'恢复'}</button><button class="btn danger" name="command" value="void">作废</button>`:''}${c.userId===user.id&&c.history.length===1?'<button class="btn" name="command" value="withdraw">撤回申请</button>':''}</div>${!handler&&!manager?'<p class="muted">当前身份不是主任务办理人。</p>':''}</form>`:notice('该办件已结束，材料与历史版本保留。')}${c.subtasks.map(t=>`<div class="pc-subtask">协办：${esc(rows('users').find(u=>u.id===t.userId)?.name||t.userId)} ${tag(t.status)}${t.userId===user.id&&t.status==='待办'&&c.status==='在办'?btn('完成协办','pc-assist-complete',c.id+':'+t.id,'small'):''}</div>`).join('')}</section><section class="panel pc-padding pc-section-space"><h2>办理时间线</h2><div class="pc-timeline">${c.history.slice().reverse().map(h=>`<div><i></i><strong>${esc(h.actor)}</strong><small>${fmt(h.at)}</small><p>${esc(h.text)}</p></div>`).join('')}</div></section></aside></div>`;
  }
